service-call.in-map:
{communicationEventTypeId:'Comment', contactMechTypeEnumId:'CmtWebForm', statusId:'CeSent',
                        fromPartyId:ec.user.userAccount.partyId, entryDate:ec.user.nowTimestamp,
                        contentType:contentType, subject:subject, body:body}

actions.script:
const commEventJoins = {
    'mantle.order.OrderHeader': {entityName: 'mantle.order.OrderCommunicationEvent', keyField: 'orderId'},
    'mantle.request.Request': {entityName: 'mantle.request.RequestCommEvent', keyField: 'requestId'},
    'mantle.work.effort.WorkEffort': {entityName: 'mantle.work.effort.WorkEffortCommEvent', keyField: 'workEffortId'},
    'moqui.resource.wiki.WikiPage': {entityName: 'mantle.party.communication.WikiPageCommunicationEvent', keyField: 'wikiPageId'}}
const workEffortJoins = {
    'mantle.request.Request': {entityName: 'mantle.request.RequestWorkEffort', keyField: 'requestId'},
    'moqui.resource.wiki.WikiPage': {entityName: 'mantle.work.effort.WikiPageWorkEffort', keyField: 'wikiPageId'}}
const noteEntities = {
    'mantle.party.Party': {entityName: 'mantle.party.PartyNote', keyField: 'partyId'},
    'mantle.work.effort.WorkEffort': {entityName: 'mantle.work.effort.WorkEffortNote', keyField: 'workEffortId'},
    'mantle.request.Request': {entityName: 'mantle.request.RequestNote', keyField: 'requestId'},
    'mantle.order.OrderHeader': {entityName: 'mantle.order.OrderNote', keyField: 'orderId'},
    'mantle.facility.Facility': {entityName: 'mantle.facility.FacilityNote', keyField: 'facilityId'}}
// the record types with a *Content entity: the 13 with create and save services, and Facility
const content = (entityName, keyField, typeField, dateField) =>
        ({entityName: entityName, keyField: keyField, typeField: typeField, dateField: dateField || 'contentDate'})
const contentEntities = {
    'mantle.party.agreement.Agreement': content('mantle.party.agreement.AgreementContent', 'agreementId', 'contentTypeEnumId'),
    'mantle.product.maintenance.AssetMaintenance': content('mantle.product.maintenance.AssetMaintenanceContent',
            'assetMaintenanceId', 'contentTypeEnumId'),
    'mantle.party.communication.CommunicationEvent': content('mantle.party.communication.CommunicationEventContent',
            'communicationEventId', 'contentTypeEnumId'),
    'mantle.account.invoice.Invoice': content('mantle.account.invoice.InvoiceContent', 'invoiceId', 'contentTypeEnumId'),
    'mantle.order.OrderHeader': content('mantle.order.OrderContent', 'orderId', 'orderContentTypeEnumId'),
    'mantle.party.Party': content('mantle.party.PartyContent', 'partyId', 'partyContentTypeEnumId'),
    'mantle.account.payment.Payment': content('mantle.account.payment.PaymentContent', 'paymentId', 'contentTypeEnumId'),
    'mantle.account.method.PaymentMethod': content('mantle.account.method.PaymentMethodContent', 'paymentMethodId', 'contentTypeEnumId'),
    'mantle.product.Product': content('mantle.product.ProductContent', 'productId', 'productContentTypeEnumId', 'fromDate'),
    'mantle.product.category.ProductCategory': content('mantle.product.category.ProductCategoryContent',
            'productCategoryId', 'categoryContentTypeEnumId', 'fromDate'),
    'mantle.request.Request': content('mantle.request.RequestContent', 'requestId', 'contentTypeEnumId'),
    'mantle.shipment.Shipment': content('mantle.shipment.ShipmentContent', 'shipmentId', 'shipmentContentTypeEnumId'),
    'mantle.work.effort.WorkEffort': content('mantle.work.effort.WorkEffortContent', 'workEffortId', 'contentTypeEnumId'),
    'mantle.facility.Facility': content('mantle.facility.FacilityContent', 'facilityId', 'facilityContentTypeEnumId')}

let recordValue
try { recordValue = ec.entity.makeValue(recordEntityName) }
catch (err) { ec.message.addError(`The record type ${recordEntityName} is not an entity`); return }
recordEntityName = recordValue.getEntityName()
recordTypeName = recordValue.getEntityNamePretty()
const keyNames = Object.keys(recordValue.getPrimaryKeys())
if (keyNames.length !== 1) {
    ec.message.addError(`The record type ${recordEntityName} has ${keyNames.length} primary key fields, a record link needs one`)
    return
}
recordKeyField = keyNames[0]
// the record under the user's filters: a record the user may not see has no links for them; someone else's
// personal contact (Party.privateOwnerUserId) is not found, with or without an entity filter
const record = checkRecord ? ec.entity.find(recordEntityName).condition(recordKeyField, recordId).one() : null
if (checkRecord && (record == null || (recordEntityName === 'mantle.party.Party' && record.privateOwnerUserId
        && record.privateOwnerUserId !== ec.user.userId))) {
    ec.message.addError(`${recordTypeName} ${recordId} not found`)
    return
}
isParty = recordEntityName === 'mantle.party.Party'
commEventJoin = commEventJoins[recordEntityName] || null
workEffortJoin = workEffortJoins[recordEntityName] || null
noteEntity = noteEntities[recordEntityName] || null
contentEntity = contentEntities[recordEntityName] || null

created = false
const eventOf = (id) => {
    if (!id) return null
    const found = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('emailMessageId', id)
            .orderBy('communicationEventId').limit(1).list()
    return found.length ? found[0] : null
}
const existing = eventOf(emailMessageId)
if (existing != null) { communicationEventId = existing.communicationEventId; return }

// TODO: once mail accounts have owners (IronStone M5) check the user may see the message
const email = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).one()
if (email == null) { ec.message.addError(`Email message ${emailMessageId} not found`); return }

const cf = ec.entity.conditionFactory
const bareAddress = (text) => {
    const match = /<([^>]+)>/.exec(text)
    return (match ? match[1] : text).trim()
}
const addressList = (text) => text ? String(text).split(/[,;]/).map(bareAddress).filter((address) => address.includes('@')) : []
const partyOf = (address, userId) => {
    if (userId) {
        const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).useCache(true).one()
        if (account?.partyId) return {partyId: account.partyId, contactMechId: null}
    }
    if (!address) return null
    const found = ec.entity.find('mantle.party.contact.PartyContactMechInfo')
            .condition('contactMechTypeEnumId', 'CmtEmailAddress')
            .condition(cf.makeCondition('infoString', 'equals', address, false, true))
            .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).orderBy('-fromDate').limit(1).list()
    return found.length ? {partyId: found[0].partyId, contactMechId: found[0].contactMechId} : null
}
const from = partyOf(addressList(email.fromAddress)[0], email.fromUserId)
const to = partyOf(addressList(email.toAddresses)[0], email.toUserId)
const statusByEmail = {ES_DRAFT: 'CeInProgress', ES_READY: 'CeReady', ES_SENT: 'CeSent', ES_RECEIVED: 'CeReceived',
    ES_VIEWED: 'CeViewed', ES_BOUNCED: 'CeBounced', ES_CANCELLED: 'CeCancelled'}
const parent = eventOf(email.parentEmailMessageId)

const out = ec.service.sync().name('create#mantle.party.communication.CommunicationEvent').parameters({
    communicationEventTypeId: 'Email', contactMechTypeEnumId: 'CmtEmailAddress', emailMessageId: emailMessageId,
    statusId: statusByEmail[email.statusId] || (email.receivedDate ? 'CeReceived' : 'CeSent'),
    fromPartyId: from?.partyId ?? null, fromContactMechId: from?.contactMechId ?? null,
    toPartyId: to?.partyId ?? null, toContactMechId: to?.contactMechId ?? null,
    parentCommEventId: parent?.communicationEventId ?? null,
    rootCommEventId: parent ? (parent.rootCommEventId || parent.communicationEventId) : null,
    entryDate: email.sentDate ?? email.receivedDate ?? ec.user.nowTimestamp, datetimeStarted: email.sentDate ?? null,
    subject: email.subject, body: email.body ?? email.bodyText, contentType: email.contentType}).call()
if (ec.message.hasError()) return
communicationEventId = out.communicationEventId
created = true

created = false
if (!communicationEventId && emailMessageId) {
    const emailOut = ec.service.sync().name('mantle.party.CommunicationServices.findOrCreate#EmailCommunicationEvent')
            .parameter('emailMessageId', emailMessageId).call()
    if (ec.message.hasError()) return
    communicationEventId = emailOut.communicationEventId
}
if (!communicationEventId) { ec.message.addError('A communicationEventId or emailMessageId is required'); return }
const commEvent = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', communicationEventId).one()
if (commEvent == null) { ec.message.addError(`Communication event ${communicationEventId} not found`); return }

const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
recordEntityName = info.recordEntityName

const createRow = (entityName, fields) => {
    ec.service.sync().name('create#' + entityName).parameters(fields).call()
    created = !ec.message.hasError()
}
if (info.isParty) {
    if (commEvent.fromPartyId === recordId || commEvent.toPartyId === recordId) {
        linkEntityName = 'mantle.party.communication.CommunicationEvent'
    } else {
        linkEntityName = 'mantle.party.communication.CommunicationEventParty'
        const partyRows = ec.entity.find(linkEntityName).condition('communicationEventId', communicationEventId)
                .condition('partyId', recordId).list()
        if (partyRows.length === 0) createRow(linkEntityName, {communicationEventId: communicationEventId, partyId: recordId, roleTypeId: '_NA_'})
    }
} else if (info.commEventJoin) {
    linkEntityName = info.commEventJoin.entityName
    const keys = {communicationEventId: communicationEventId, [info.commEventJoin.keyField]: recordId}
    if (ec.entity.find(linkEntityName).condition(keys).one() == null) createRow(linkEntityName, keys)
} else {
    linkEntityName = 'mantle.party.communication.CommunicationEventRecord'
    const keys = {communicationEventId: communicationEventId, recordEntityName: recordEntityName, recordId: recordId}
    if (ec.entity.find(linkEntityName).condition(keys).one() == null)
        createRow(linkEntityName, Object.assign({linkedByUserId: ec.user.userId, linkedDate: ec.user.nowTimestamp}, keys))
}
if (ec.message.hasError()) return

if (created && notifyFollowers) ec.service.sync().name('mantle.party.CommunicationServices.notify#RecordFollowers').parameters({
    recordEntityName: recordEntityName, recordId: recordId, kind: commEvent.communicationEventTypeId === 'Comment' ? 'notes' : 'messages',
    communicationEventId: communicationEventId, subject: commEvent.subject, body: commEvent.body, recordUrl: recordUrl}).call()

unlinked = false
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
const removeRows = (entityName, keys) => {
    for (const row of ec.entity.find(entityName).condition(keys).list()) {
        ec.service.sync().name('delete#' + entityName).parameters(row.getPrimaryKeys()).call()
        if (ec.message.hasError()) return
        unlinked = true
    }
}
if (info.isParty) removeRows('mantle.party.communication.CommunicationEventParty',
        {communicationEventId: communicationEventId, partyId: recordId, roleTypeId: '_NA_'})
if (info.commEventJoin) removeRows(info.commEventJoin.entityName,
        {communicationEventId: communicationEventId, [info.commEventJoin.keyField]: recordId})
removeRows('mantle.party.communication.CommunicationEventRecord',
        {communicationEventId: communicationEventId, recordEntityName: info.recordEntityName, recordId: recordId})

entryList = []
plannedActivities = []
hasMore = false
failedSources = []
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
recordEntityName = info.recordEntityName

const cf = ec.entity.conditionFactory
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const kindNames = {message: 'message', messages: 'message', note: 'note', notes: 'note', activity: 'activity',
    activities: 'activity', change: 'change', changes: 'change', file: 'file', files: 'file'}
const kindValues = kinds == null ? [] : (typeof kinds === 'string' ? kinds.split(',') : Array.from(kinds))
const wanted = new Set(kindValues.map((kind) => kindNames[String(kind).trim()]).filter((kind) => kind))
const wants = (kind) => wanted.size === 0 || wanted.has(kind)
const start = pageIndex * pageSize
const need = start + pageSize + 1
const beforeMillis = toMillis(beforeDate)
const before = beforeMillis == null ? null : new Date(beforeMillis)
const entries = []

// one source: a failure (an exception or error messages) is logged and the source left out
const runSource = (name, run) => {
    try {
        run()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        ec.message.clearErrors()
        ec.logger.error(`Record timeline of ${recordEntityName} ${recordId}: the ${name} source failed and is left out: ${err}`)
        failedSources.push(name)
    }
}
// a source service in a transaction of its own, so its failure rolls back only that
const callSource = (serviceName, parameters) =>
        ec.service.sync().name(serviceName).parameters(parameters).requireNewTransaction(true).call()

// messages and notes: communication events
if (wants('message') || wants('note')) runSource('communicationEvents', () => {
    const ids = new Set()
    if (info.isParty) {
        const typeIds = ec.entity.find('mantle.party.communication.CommunicationEventType').useCache(true).list()
                .map((type) => type.communicationEventTypeId).join(',')
        const parameters = {partyId: recordId, communicationEventTypeId: typeIds, includeListPosts: includeListPosts,
            orderByField: '-entryDate', pageIndex: 0, pageSize: need}
        if (before) parameters.entryDate_thru = new Date(beforeMillis - 1)
        const found = callSource('mantle.party.CommunicationServices.find#PartyCommunicationEvents', parameters)
        if (ec.message.hasError()) return
        for (const commEvent of found.commEventList) ids.add(commEvent.communicationEventId)
    } else {
        if (info.commEventJoin) for (const row of ec.entity.find(info.commEventJoin.entityName)
                .condition(info.commEventJoin.keyField, recordId).list()) ids.add(row.communicationEventId)
        for (const row of ec.entity.find('mantle.party.communication.CommunicationEventRecord')
                .condition('recordEntityName', recordEntityName).condition('recordId', recordId).list()) ids.add(row.communicationEventId)
    }
    if (ids.size === 0) return
    const idList = Array.from(ids)
    // for a record, the replies in the threads of its events too
    const idCondition = info.isParty ? cf.makeCondition('communicationEventId', 'in', idList) : cf.makeCondition([
        cf.makeCondition('communicationEventId', 'in', idList), cf.makeCondition('rootCommEventId', 'in', idList)], 'or')
    let find = ec.entity.find('mantle.party.communication.CommunicationEvent').condition(idCondition)
            .condition(cf.makeCondition('statusId', 'not-equals', 'CeCancelled', true)).orderBy('-entryDate').limit(need)
    if (before) find = find.condition(cf.makeCondition('entryDate', 'less', before))
    for (const value of find.list()) {
        const commEvent = value.getMap()
        const kind = commEvent.communicationEventTypeId === 'Comment' ? 'note' : 'message'
        if (!wants(kind)) continue
        entries.push({kind: kind, date: commEvent.entryDate ?? commEvent.datetimeStarted ?? commEvent.lastUpdatedStamp,
            authorPartyId: commEvent.fromPartyId ?? null, authorUserId: null, title: commEvent.subject ?? null,
            body: commEvent.body ?? null, contentType: commEvent.contentType ?? null, statusId: commEvent.statusId ?? null,
            source: 'mantle.party.communication.CommunicationEvent', communicationEventId: commEvent.communicationEventId,
            communicationEventTypeId: commEvent.communicationEventTypeId, fromPartyId: commEvent.fromPartyId ?? null,
            toPartyId: commEvent.toPartyId ?? null, parentCommEventId: commEvent.parentCommEventId ?? null,
            rootCommEventId: commEvent.rootCommEventId ?? null, emailMessageId: commEvent.emailMessageId ?? null,
            contactListId: commEvent.contactListId ?? null})
    }
})

// notes: the record's *Note rows
if (wants('note') && info.noteEntity) runSource('notes', () => {
    let find = ec.entity.find(info.noteEntity.entityName).condition(info.noteEntity.keyField, recordId)
            .orderBy('-noteDate').limit(need)
    if (before) find = find.condition(cf.makeCondition('noteDate', 'less', before))
    for (const value of find.list()) {
        const note = value.getMap()
        entries.push({kind: 'note', date: note.noteDate, authorPartyId: null, authorUserId: note.userId ?? null,
            title: null, body: note.noteText ?? null, contentType: 'text/plain', statusId: null,
            source: info.noteEntity.entityName, noteDate: note.noteDate, internalNote: note.internalNote ?? null})
    }
})

// activities: the record's calls, emails, to-dos and meetings; done ones in the timeline, open ones planned
if (wants('activity')) runSource('activities', () => {
    const ids = new Set()
    if (info.workEffortJoin) for (const row of ec.entity.find(info.workEffortJoin.entityName)
            .condition(info.workEffortJoin.keyField, recordId).list()) ids.add(row.workEffortId)
    for (const row of ec.entity.find('mantle.work.effort.WorkEffortRecord').condition('recordEntityName', recordEntityName)
            .condition('recordId', recordId).list()) ids.add(row.workEffortId)
    if (ids.size === 0) return
    const nowMillis = toMillis(ec.user.nowTimestamp)
    const activities = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', Array.from(ids))
            .condition('purposeEnumId', 'in', ['WepPhoneCall', 'WepEmail', 'WepToDo', 'WepMeeting']).list()
    for (const value of activities) {
        const activity = value.getMap()
        if (activity.statusId === 'WeCancelled') continue
        const assignees = ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', activity.workEffortId)
                .condition('roleTypeId', 'Assignee').condition(cf.makeConditionDate('fromDate', 'thruDate', null))
                .orderBy('-fromDate').limit(1).list()
        const assigneePartyId = assignees.length ? assignees[0].partyId : null
        if (activity.statusId === 'WeComplete' || activity.statusId === 'WeClosed') {
            const date = activity.actualCompletionDate ?? activity.estimatedCompletionDate ?? activity.actualStartDate ??
                    activity.estimatedStartDate ?? activity.lastUpdatedStamp
            if (beforeMillis != null && toMillis(date) >= beforeMillis) continue
            entries.push({kind: 'activity', date: date, authorPartyId: assigneePartyId, authorUserId: null,
                title: activity.workEffortName ?? null, body: activity.description ?? null, contentType: null,
                statusId: activity.statusId, source: 'mantle.work.effort.WorkEffort', workEffortId: activity.workEffortId,
                purposeEnumId: activity.purposeEnumId})
        } else {
            const due = activity.purposeEnumId === 'WepMeeting' ? (activity.estimatedStartDate ?? activity.estimatedCompletionDate)
                    : (activity.estimatedCompletionDate ?? activity.estimatedStartDate)
            const dueMillis = toMillis(due)
            plannedActivities.push({workEffortId: activity.workEffortId, workEffortName: activity.workEffortName ?? null,
                description: activity.description ?? null, purposeEnumId: activity.purposeEnumId, statusId: activity.statusId,
                dueDate: dueMillis == null ? null : new Date(dueMillis), overdue: dueMillis != null && dueMillis < nowMillis,
                assigneePartyId: assigneePartyId})
        }
    }
    const dueOf = (activity) => activity.dueDate == null ? Number.MAX_SAFE_INTEGER : activity.dueDate.getTime()
    plannedActivities.sort((left, right) => dueOf(left) - dueOf(right))
})

// changes: the entity audit log of the record's enable-audit-log fields
if (wants('change')) runSource('auditLog', () => {
    let find = ec.entity.find('moqui.entity.EntityAuditLog').condition('changedEntityName', recordEntityName)
            .condition('pkPrimaryValue', recordId).condition(cf.makeCondition('pkSecondaryValue', 'is-null', null))
            .orderBy('-changedDate').limit(need).disableAuthz()
    if (before) find = find.condition(cf.makeCondition('changedDate', 'less', before))
    const statusDescription = (statusId) => {
        if (!statusId) return null
        const status = ec.entity.find('moqui.basic.StatusItem').condition('statusId', statusId).useCache(true).one()
        return status ? status.description : statusId
    }
    for (const value of find.list()) {
        const change = value.getMap()
        const isStatus = /statusId$/i.test(change.changedFieldName || '')
        const oldDescription = isStatus ? statusDescription(change.oldValueText) : null
        const newDescription = isStatus ? statusDescription(change.newValueText) : null
        entries.push({kind: 'change', date: change.changedDate, authorPartyId: null, authorUserId: change.changedByUserId ?? null,
            title: change.changedFieldName, body: `${oldDescription ?? change.oldValueText ?? ''} → ${newDescription ?? change.newValueText ?? ''}`,
            contentType: 'text/plain', statusId: null, source: 'moqui.entity.EntityAuditLog',
            auditHistorySeqId: change.auditHistorySeqId, fieldName: change.changedFieldName, oldValue: change.oldValueText ?? null,
            newValue: change.newValueText ?? null, oldValueDescription: oldDescription, newValueDescription: newDescription,
            changeReason: change.changeReason ?? null})
    }
})

// files: the record's *Content rows
if (wants('file') && info.contentEntity) runSource('content', () => {
    const contentInfo = info.contentEntity
    let find = ec.entity.find(contentInfo.entityName).condition(contentInfo.keyField, recordId)
            .orderBy('-' + contentInfo.dateField).limit(need)
    if (before) find = find.condition(cf.makeCondition(contentInfo.dateField, 'less', before))
    for (const value of find.list()) {
        const row = value.getMap()
        const location = row.contentLocation ? String(row.contentLocation) : ''
        entries.push({kind: 'file', date: row[contentInfo.dateField], authorPartyId: null, authorUserId: row.userId ?? null,
            title: location ? location.substring(location.lastIndexOf('/') + 1) : null, body: row.description ?? null,
            contentType: null, statusId: null, source: contentInfo.entityName, contentKey: value.getPrimaryKeys(),
            contentLocation: row.contentLocation ?? null, contentTypeEnumId: row[contentInfo.typeField] ?? null})
    }
})

// registered sources, such as a chat room bound to the record
const registered = ec.entity.find('moqui.service.ServiceRegister').condition('serviceTypeEnumId', 'RecordTimelineSource')
        .useCache(true).list()
for (const register of registered) runSource(register.serviceRegisterId, () => {
    const out = callSource(register.serviceName, {recordEntityName: recordEntityName, recordId: recordId,
        kinds: Array.from(wanted), beforeDate: before, limit: need})
    if (ec.message.hasError()) return
    for (const entry of (out?.entryList ?? [])) {
        const kind = kindNames[entry.kind] || entry.kind
        if (!wants(kind)) continue
        if (beforeMillis != null && toMillis(entry.date) >= beforeMillis) continue
        entries.push(Object.assign({source: register.serviceName}, entry, {kind: kind}))
    }
})

// the union, newest first, and the page
const dateOf = (entry) => toMillis(entry.date) ?? 0
entries.sort((left, right) => dateOf(right) - dateOf(left))
hasMore = entries.length > start + pageSize
const page = entries.slice(start, start + pageSize)
for (const entry of page) entry.date = entry.date == null ? null : new Date(dateOf(entry))

// the attachments of the messages and notes shown
const commEventIds = page.filter((entry) => entry.communicationEventId).map((entry) => entry.communicationEventId)
if (commEventIds.length) runSource('attachments', () => {
    const byEvent = {}
    for (const value of ec.entity.find('mantle.party.communication.CommunicationEventContent')
            .condition('communicationEventId', 'in', commEventIds).orderBy('sequenceNum,contentDate').list()) {
        const row = value.getMap()
        const location = row.contentLocation ? String(row.contentLocation) : ''
        ;(byEvent[row.communicationEventId] ??= []).push({communicationEventContentId: row.communicationEventContentId,
            contentLocation: row.contentLocation ?? null, fileName: location ? location.substring(location.lastIndexOf('/') + 1) : null,
            contentTypeEnumId: row.contentTypeEnumId ?? null, description: row.description ?? null})
    }
    for (const entry of page) if (entry.communicationEventId) entry.attachments = byEvent[entry.communicationEventId] ?? []
})
// the author's party of the entries that have only a user
const userIds = Array.from(new Set(page.filter((entry) => entry.authorUserId && !entry.authorPartyId).map((entry) => entry.authorUserId)))
if (userIds.length) runSource('authors', () => {
    const partyByUser = {}
    for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', userIds).disableAuthz().list())
        partyByUser[account.userId] = account.partyId
    for (const entry of page) if (entry.authorUserId && !entry.authorPartyId) entry.authorPartyId = partyByUser[entry.authorUserId] ?? null
})
entryList = page

mentionedUserIds = []
notifiedFollowerUserIds = []
let rootCommEventId = null
if (parentCommEventId) {
    const parent = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', parentCommEventId).one()
    if (parent == null) { ec.message.addError(`Communication event ${parentCommEventId} not found`); return }
    rootCommEventId = parent.rootCommEventId || parentCommEventId
}
const messageOut = ec.service.sync().name('mantle.party.CommunicationServices.create#Message').parameters({
    communicationEventTypeId: 'Comment', contactMechTypeEnumId: 'CmtWebForm', statusId: 'CeSent', subject: subject,
    body: body, contentType: contentType, parentCommEventId: parentCommEventId, rootCommEventId: rootCommEventId}).call()
if (ec.message.hasError()) return
communicationEventId = messageOut.communicationEventId
const linkOut = ec.service.sync().name('mantle.party.CommunicationServices.link#CommunicationEventRecord')
        .parameters({communicationEventId: communicationEventId, recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
linkEntityName = linkOut.linkEntityName

const notifyParameters = {recordEntityName: linkOut.recordEntityName, recordId: recordId, communicationEventId: communicationEventId,
    subject: subject, body: body, recordUrl: recordUrl}
if (mentionUserIds?.length || mentionPartyIds?.length) {
    const mentionOut = ec.service.sync().name('mantle.party.CommunicationServices.notify#RecordMention')
            .parameters(Object.assign({mentionUserIds: mentionUserIds, mentionPartyIds: mentionPartyIds}, notifyParameters)).call()
    if (ec.message.hasError()) return
    mentionedUserIds = mentionOut.notifiedUserIds
}
const followerOut = ec.service.sync().name('mantle.party.CommunicationServices.notify#RecordFollowers')
        .parameters(Object.assign({kind: 'notes', excludeUserIds: mentionedUserIds}, notifyParameters)).call()
if (ec.message.hasError()) return
notifiedFollowerUserIds = followerOut.notifiedUserIds

notifiedUserIds = []
const userIds = new Set(mentionUserIds ? Array.from(mentionUserIds) : [])
if (mentionPartyIds?.length) for (const account of ec.entity.find('moqui.security.UserAccount')
        .condition('partyId', 'in', Array.from(mentionPartyIds)).disableAuthz().list()) userIds.add(account.userId)
userIds.delete(authorUserId)
if (userIds.size === 0) return
const message = ec.service.sync().name('mantle.party.CommunicationServices.make#RecordNotificationMessage').parameters({
    recordEntityName: recordEntityName, recordId: recordId, communicationEventId: communicationEventId, subject: subject,
    body: body, authorUserId: authorUserId}).call().message
try {
    const nm = ec.makeNotificationMessage().topic('ChatterMention').message(message).userIds(Array.from(userIds))
    if (recordUrl) nm.link(recordUrl)
    nm.send()
    notificationMessageId = nm.getNotificationMessageId()
    notifiedUserIds = Array.from(nm.getNotifyUserIds() ?? [])
} catch (err) {
    ec.logger.error(`Mention notification for ${recordEntityName} ${recordId} not sent: ${err}`)
}

notifiedUserIds = []
const flagFields = {messages: 'notifyMessages', notes: 'notifyNotes', activities: 'notifyActivities', changes: 'notifyChanges'}
const flagField = flagFields[kind]
if (!flagField) { ec.message.addError(`Follower kind ${kind} is not one of messages, notes, activities, changes`); return }
const excluded = new Set(excludeUserIds ? Array.from(excludeUserIds) : [])
excluded.add(authorUserId)
const userIds = ec.entity.find('mantle.party.communication.RecordFollower').condition('recordEntityName', recordEntityName)
        .condition('recordId', recordId).condition(flagField, 'Y').list()
        .map((follower) => follower.userId).filter((userId) => !excluded.has(userId))
if (userIds.length === 0) return
const message = ec.service.sync().name('mantle.party.CommunicationServices.make#RecordNotificationMessage').parameters({
    recordEntityName: recordEntityName, recordId: recordId, communicationEventId: communicationEventId, subject: subject,
    body: body, authorUserId: authorUserId}).call().message
message.kind = kind
message.workEffortId = workEffortId ?? null
try {
    const nm = ec.makeNotificationMessage().topic('RecordFollow').message(message).userIds(userIds)
    if (recordUrl) nm.link(recordUrl)
    nm.send()
    notificationMessageId = nm.getNotificationMessageId()
    notifiedUserIds = Array.from(nm.getNotifyUserIds() ?? [])
} catch (err) {
    ec.logger.error(`Follower notification for ${recordEntityName} ${recordId} not sent: ${err}`)
}

let recordTypeName = recordEntityName.substring(recordEntityName.lastIndexOf('.') + 1)
try { recordTypeName = ec.entity.makeValue(recordEntityName).getEntityNamePretty() } catch (err) { /* the short name */ }
const author = authorUserId ? ec.entity.find('moqui.security.UserAccount').condition('userId', authorUserId).disableAuthz().one() : null
const text = body ? String(body).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim() : ''
message = {recordEntityName: recordEntityName, recordId: recordId, recordName: `${recordTypeName} ${recordId}`,
    communicationEventId: communicationEventId ?? null, authorUserId: authorUserId ?? null,
    authorName: author ? (author.userFullName || author.username) : 'Someone', subject: subject ?? null,
    summary: subject || (text.length > 120 ? text.substring(0, 117) + '...' : text)}

if (!userId) { ec.message.addError('A user is required to follow a record'); return }
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
const flagFields = {messages: 'notifyMessages', notes: 'notifyNotes', activities: 'notifyActivities', changes: 'notifyChanges'}
const keys = {recordEntityName: info.recordEntityName, recordId: recordId, userId: userId}
const existing = ec.entity.find('mantle.party.communication.RecordFollower').condition(keys).one()
let flags = null
const kindList = (kinds == null ? [] : (typeof kinds === 'string' ? kinds.split(',') : Array.from(kinds)))
        .map((kind) => String(kind).trim()).filter((kind) => kind)
if (kindList.length) {
    const unknown = kindList.filter((kind) => !flagFields[kind])
    if (unknown.length) { ec.message.addError(`Follower kinds ${unknown.join(', ')} are not messages, notes, activities or changes`); return }
    flags = {}
    for (const [kind, field] of Object.entries(flagFields)) flags[field] = kindList.includes(kind) ? 'Y' : 'N'
}
if (existing != null) {
    fromDate = existing.fromDate
    if (flags) ec.service.sync().name('update#mantle.party.communication.RecordFollower').parameters(Object.assign({}, keys, flags)).call()
} else {
    fromDate = ec.user.nowTimestamp
    ec.service.sync().name('create#mantle.party.communication.RecordFollower').parameters(Object.assign({fromDate: fromDate},
            flags || {notifyMessages: 'Y', notifyNotes: 'Y', notifyActivities: 'Y', notifyChanges: 'N'}, keys)).call()
}

let entityName = recordEntityName
try { entityName = ec.entity.makeValue(recordEntityName).getEntityName() } catch (err) { /* as given */ }
const keys = {recordEntityName: entityName, recordId: recordId, userId: userId}
if (ec.entity.find('mantle.party.communication.RecordFollower').condition(keys).one() != null)
    ec.service.sync().name('delete#mantle.party.communication.RecordFollower').parameters(keys).call()

followerList = []
isFollowing = false
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
for (const follower of ec.entity.find('mantle.party.communication.RecordFollower').condition('recordEntityName', info.recordEntityName)
        .condition('recordId', recordId).orderBy('fromDate').list()) {
    const account = ec.entity.find('moqui.security.UserAccount').condition('userId', follower.userId).disableAuthz().one()
    followerList.push({userId: follower.userId, username: account?.username ?? null, userFullName: account?.userFullName ?? null,
        partyId: account?.partyId ?? null, notifyMessages: follower.notifyMessages, notifyNotes: follower.notifyNotes,
        notifyActivities: follower.notifyActivities, notifyChanges: follower.notifyChanges, fromDate: follower.fromDate})
    if (follower.userId === ec.user.userId) isFollowing = true
}
